    var classBDetours: [APIDetour]?
    var flown: String?
    var options: [APIAltitudeOption]?
    var airway: APIAirwayAltitudes?
    var climbMin: Double?
    var densityAltitudeFt: Double?
    var distanceNm: Double?
    var eteMin: Double?
    var from: String?
    var fuelBurnGph, fuelGal, groundMin, groundspeedKt: Double?
    var hold: APILegHold?
    var magneticCourseDeg: Double?
    var magneticHeadingDeg: Double?
    var magneticVariationDeg: Double?
    var oatC, powerPct: Double?
    var procedure: APILegProcedure?
    var tasKt: Double?
    var to: String?
    var toc: APITopOfClimb?
    var tod: APITopOfDescent?
    var trueCourseDeg: Double?
    var trueHeadingDeg, wcaDeg: Double?
    var wind: APIWind?
    var totals: APITotals?
}

