/// One dead-reckoning leg. `wind` is None when no winds-aloft station
/// is near enough, which is not the same as calm: groundspeed then falls
/// back to true airspeed. groundspeed/ETE/fuel are None when the wind
/// exceeds true airspeed, i.e. the leg cannot be flown.
///
/// The true airspeed and fuel flow are the aeroplane's in the leg's own
/// air (wingtip.performance): its cruise figures are at a reference
/// altitude on a standard day, and the forecast temperature at this
/// altitude gives the density altitude they are flown at, at the power
/// it allows -- the cruise power, or less where full throttle cannot
/// make it. `oat_c` is None where no forecast temperature was near: a
/// standard day is assumed there.
// MARK: - APILeg
struct APILeg: Codable, Equatable, Sendable {
    var airway: APIAirwayAltitudes?
    var altitudeFt: Double
    var climbMin: Double?
    var densityAltitudeFt: Double?
    var distanceNm: Double
    var eteMin: Double?
    var from: String
    var fuelBurnGph, fuelGal: Double?
    var groundMin: Double?
    var groundspeedKt: Double?
    var hold: APILegHold?
    var magneticCourseDeg: Double
    var magneticHeadingDeg: Double?
    var magneticVariationDeg: Double
    var oatC: Double?
    var powerPct: Double?
    var procedure: APILegProcedure?
    var tasKt: Double?
    var to: String
    var toc: APITopOfClimb?
    var tod: APITopOfDescent?
    var trueCourseDeg: Double
    var trueHeadingDeg, wcaDeg: Double?
    var wind: APIWind?
}

/// An approach's plate's plan view placed on the map (wingtip.plates): the
/// FAA's plate of `name` in d-TPP cycle `cycle`, its picture at
/// /api/approach-plate/{cycle}/{ident}/{procedure}.png, black on clear,
/// north up between these latitudes and longitudes, as the plate's own
/// georeference places it; `fixes` the approach's fixes inside it;
/// `circling` whether the plate publishes circling minimums, so a pilot
/// flying the approach may circle to land on another runway; `page` the
/// whole page placed (PlatePage), None where its page is turned in the
/// PDF and so not placed.
// MARK: - APIPlateOverlay
struct APIPlateOverlay: Codable, Equatable, Sendable {
    var circling: Bool
    var cycle: String
    var east: Double
    var fixes: [String]
    var name: String
    var north: Double
    var page: APIPlatePage?
    var south, west: Double
}

/// An approach plate's whole page placed on the map (wingtip.plate_page):
/// its picture at /api/approach-plate-page/{cycle}/{ident}/{procedure}.png,
/// greyscale on white, `width` by `height` pixels, drawn between its four
/// corners on the ground, which put its plan view where the plate's own
/// georeference does; the rest of the page goes round it at the same scale
/// and turn, as ForeFlight lays a plate on its chart. The page may turn a
/// little from north up (the plate's Lambert projection's meridians lean),
/// so it is drawn between the four corners, not in a box.
// MARK: - APIPlatePage
struct APIPlatePage: Codable, Equatable, Sendable {
    var bottomLeft, bottomRight: APIPlateCorner
    var height: Int
    var topLeft, topRight: APIPlateCorner
    var width: Int
}

/// A corner of a plate's page on the ground.
// MARK: - APIPlateCorner
struct APIPlateCorner: Codable, Equatable, Sendable {
    var lat, lon: Double
}

/// One procedure drawn with the transition picked (wingtip.procedures):
/// its lines, holds and fixes, from the CIFP of `cycle`.
// MARK: - APIProcedureDrawing
struct APIProcedureDrawing: Codable, Equatable, Sendable {
    var airport: String
    var approach: APIApproachFacts?
    var cycle: String
    var finalCourseDeg: Int?
    var fixes: [APIProcedureFix]
    var glidepathDeg: Double?
    var holds: [APIProcedureHold]
    var id, kind: String
    var lines: [APIProcedureLine]
    var missedLegs: [APIProcedureMissedLeg]?
    var name: String
    var runwayPath: APIProcedureRunwayPath?
    var stale: Bool?
    var transition: String?
}

/// What the CIFP says of an approach besides its legs
/// (wingtip.approach_facts): its runway, the altitudes coded beside its
/// fixes' limits, and the levels of service it authorises (ARINC 424-19
/// 5.275, 5.276: "LPV", "LNAV/VNAV", "LNAV", ...). No decision altitude or
/// MDA: those are the plate's minimums alone.
// MARK: - APIApproachFacts
struct APIApproachFacts: Codable, Equatable, Sendable {
    var coded: [APIApproachCoded]?
    var levels: [String]?
    var runway: APIApproachRunway?
}

/// An altitude a final codes beside a fix's limits (ARINC 424-18 5.29,
/// its second altitude): `code` "G" or "H" the glide slope's at the final
/// approach fix, "I" or "J" the glide slope's intercept at the final
/// approach course fix, "V" the vertical path's at a step-down fix.
// MARK: - APIApproachCoded
struct APIApproachCoded: Codable, Equatable, Sendable {
    var code, fix: String
    var ft: Int
}

/// The approach's runway as the CIFP's runway record gives it: its
/// threshold (`ident` "RW36"), the threshold's elevation (ARINC 424-18
/// 5.68) and the threshold crossing height (5.67), ft; and its touchdown
/// zone elevation, ft MSL to a tenth, from NASR (APT_RWY_END's TDZ_ELEV),
/// None where NASR has none.
// MARK: - APIApproachRunway
struct APIApproachRunway: Codable, Equatable, Sendable {
    var ident: String
    var lat, lon: Double
    var tchFt: Int
    var tdzeFt: Double?
    var thresholdFt: Int
}

/// A fix of a drawn procedure: its `roles` on an approach (IAF, IF,
/// FAF, MAP, hold), the altitudes it is crossed at -- at or above
/// `min_ft`, at or below `max_ft`, at both where they are one -- and the
/// speed it is crossed at, `speed_limit` saying whether that is the
/// speed ("at"), a minimum ("min") or a maximum ("max"; ARINC 424-18
/// 5.261). `missed` where it is on the missed
/// approach alone.
// MARK: - APIProcedureFix
struct APIProcedureFix: Codable, Equatable, Sendable {
    var ident: String
    var lat, lon: Double
    var maxFt, minFt: Int?
    var missed: Bool
    var roles: [String]
    var speedKt: Int?
    var speedLimit: String?
    var verticalAngleDeg: Double?
}

/// A holding pattern of a drawn procedure, or its procedure turn: at `fix`, its inbound
/// course `inbound_deg` true, its turns right or left (`turn`), drawn to
/// a light airplane's size (the engine's paths.rs, HOLD_SPEED_KT).
// MARK: - APIProcedureHold
struct APIProcedureHold: Codable, Equatable, Sendable {
    var fix: String
    var inboundDeg: Int
    var kind: String?
    var missed: Bool
    var points: [[Double]]
    var turn: String
}

/// A line of a drawn procedure, its points latitude and longitude:
/// an approach's `transition`, its `final` and its `missed` approach; an
/// arrival's or departure's enroute `transition`, `common` route, or a
/// `runway` transition, `name` the transition's ("RW08").
// MARK: - APIProcedureLine
struct APIProcedureLine: Codable, Equatable, Sendable {
    var name: String?
    var points: [[Double]]
    var role: String
}

/// A leg of an approach's missed approach, in the order flown, as its
/// words are made: `path` its ARINC 424-18 path and terminator (5.21: CA
/// a course to an altitude, VA a heading to one, VI a heading to an
/// intercept, CF and TF to a fix, DF direct to one, HM, HA and HF a
/// hold), `fix` the fix it goes to, `course_deg` its course or heading
/// magnetic, `turn` which way it turns, and the altitudes it climbs to
/// (at or above `min_ft`, at or below `max_ft`).
// MARK: - APIProcedureMissedLeg
struct APIProcedureMissedLeg: Codable, Equatable, Sendable {
    var courseDeg: Int?
    var fix: String?
    var maxFt, minFt: Int?
    var path: String
    var turn: String?
}

/// The path an approach's final comes down, placed (wingtip.procedures):
/// `deg` below level, into `fix`, its runway's threshold at `lat`/`lon`,
/// crossed at `ft` MSL -- the threshold's elevation and its crossing
/// height (ARINC 424-18 5.70).
// MARK: - APIProcedureRunwayPath
struct APIProcedureRunwayPath: Codable, Equatable, Sendable {
    var deg: Double
    var fix: String
    var ft: Int
    var lat, lon: Double
}

/// A field's instrument procedures, approaches first, from the CIFP
